def fibonacci(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def test_fibonacci_8():
    assert fibonacci(8) == 21


if __name__ == "__main__":
    test_fibonacci_8()
    print("fibonacci(8) =", fibonacci(8))
    print("PASS")

